def apply_details(model):
    nodes=model['nodes']; parents={id:[] for id in nodes}
    for n in nodes.values():
        for c in n['children']:parents[c].append(n['id'])
    def ancestors(id):
        todo=parents[id][:];seen={id}
        for x in todo:
            if x in seen:continue
            seen.add(x);yield nodes[x];todo.extend(parents[x])
    def body_profile(n):
        if n['id'] in BODY_IDS:return BODY_IDS[n['id']]
        if n['id'].startswith('office-register-'):return 'tribunal'
        if n['kind'] not in BODY_KINDS:return None
        title=n['title'].lower()
        # A bare job title is a post, even if the source table used a heading cell.
        if re.fullmatch(r'(?:chairman|chairperson|president|joint managing director|chief executive officer|j[ot][i.]?\.? director|director|commissioner)',title):return None
        for pattern,key in BODY_RULES:
            if re.search(pattern,title):return key
        return None
    def context(n):
        for a in ancestors(n['id']):
            if body_profile(a) or a['id'].startswith('dept-') or a['kind']=='District directory':return a
        return next((a for a in ancestors(n['id']) if a['id']!='root'),None)
    counts=Counter();fallback=[];unmatched_bodies=[]
    for n in nodes.values():
        old=n['role'];id=n['id'];t=n['title'].lower();k=n['kind'];ctx=context(n)
        profile_key=CORE_IDS.get(id);mode='office';isbody=body_profile(n)
        if id.startswith('dept-'):
            slug=id[5:];assert slug in DEPT_ACTIONS,slug
            scope=n['title']
            details={'description':f'This portfolio coordinates policy, programme priorities and government-level administration for {scope}. Secretariat officers examine proposals and required consultations; the relevant directorates, agencies and local offices implement decisions within their own assigned powers.',
                'actions':DEPT_ACTIONS[slug].split('|'),
                'limits':['A portfolio connection does not make every listed body a direct subordinate. Statutory authorities and local bodies retain the functions given to them by law.','A specific licence, inspection, benefit or spending sanction must be handled by the officer empowered under the applicable rules.'],
                'example':f'A proposal concerning {scope} is examined for policy, budget and implementation requirements, then sent to the appropriate authority before instructions are issued.',
                'basis':'Department overview','profile':'department','qualified':True,
                'sourceNote':'Published portfolio and directory scope, with a general explanation of departmental work. Exact officer-level delegations are not supplied by this directory.'}
        else:
            if not profile_key:
                if k=='MLA listing':profile_key='mla'
                elif k=='MLC listing':profile_key='mlc'
                elif k=='MP listing':profile_key='mp'
                elif k=='Commission membership' or 'information commissioner' in t:profile_key='information-commission'
                elif t=='state election commissioner':profile_key='election-commission'
                elif t=='speaker':profile_key='speaker'
                elif t=='chairman' and 'legislative-council-chairman' in n['source']:profile_key='council-chair'
                elif t=='chief justice':profile_key='chief-justice'
                elif k=='Judicial office' and ('judge' in t or 'justice' in t):profile_key='high-court-judge'
                elif k=='Court administration' or (ctx and ctx['id']=='judiciary' and 'registrar' in t):profile_key='court-registry'
                elif k=='Advisory role':profile_key='adviser'
                elif t in ['legislative assembly','legislative council']:profile_key='legislature'
                elif k=='Portfolio responsibility' or id.startswith('minister'):profile_key='minister'
                elif k=='District directory listing':profile_key='police-command' if 'police' in t else 'additional-collector' if 'additional' in t else 'collector'
                elif isbody:profile_key=isbody;mode='institution'
                elif k in DIRECTORY_KINDS or id in ['root','departments','cmdept','districts','advisors','mlas','mlcs','parliament']:mode='directory'
                else:
                    # Name-first advocate tables carry the function in an ancestor or the second column.
                    lineage=list(ancestors(id));lineage_ids={a['id'] for a in lineage}
                    if 'n920' in lineage_ids:profile_key='public-prosecution'
                    elif lineage_ids&{'n873','n874','n886'}:profile_key='government-lawyer'
                    else:
                        for pattern,key in POST_RULES:
                            if re.search(pattern,t):profile_key=key;break
                        if not profile_key and 'advocate general' in n['sub'].lower():profile_key='government-lawyer'
            if mode=='directory':
                directory_name=n['title']
                if k=='Secretariat directory grouping':
                    text=f'This page brings together the Secretariat contacts published for {directory_name}. The officials handle their allocated policy and administrative files; the directory heading itself is not a separate decision-making authority.'
                elif k=='District directory':
                    text=f'This is the geographic directory for {directory_name}. It links the district’s published civil-administration and police contacts, whose powers and reporting arrangements remain separate.'
                elif id=='public-bodies':
                    text='This is a discovery page for public bodies, commissions and tribunals. They are grouped here so they can be found; they do not form one organisation or one reporting chain.'
                else:text=f'This is a navigation or membership page for {directory_name}. It brings related published entries together; each actual office, member or institution has its own role and authority.'
                details={'description':text,'actions':['Open a listed office or institution to see its responsibilities','Follow the relevant branch to find published contacts and official sources','Use the map where a verified district or Assembly association is available'],
                    'limits':['This directory heading cannot issue orders, grant approvals, decide cases or exercise the powers of the entries beneath it.'],
                    'example':'Choose a named office in this branch to see what it does and which matters require another competent authority.',
                    'basis':'Directory guide','profile':'directory','qualified':False,'sourceNote':'This explanation describes how the atlas organises published records; it does not create an administrative body.'}
            else:
                if not profile_key:profile_key='specialist-support';fallback.append(id)
                if profile_key=='secretariat-officer' and ctx and body_profile(ctx) and not re.search(r'to gov|government|chief minister|^apc',t):profile_key='institution-secretary'
                p=PROFILES[profile_key];description=p['description'];limits=p['limits'][:]
                if mode=='institution':
                    description=f"{n['title']}: {description[0].lower()+description[1:]}"
                elif ctx and profile_key not in CORE_FAMILIES and id not in BODY_IDS:
                    description+=f" In this directory, the post is listed within {ctx['title']}."
                if k=='MLA listing':description+=f" The listed Assembly constituency is {n['title']}."
                if k=='MLC listing' and n['sub']:description+=f" The source lists this member under: {n['sub']}."
                if profile_key=='minister':
                    portfolio=[nodes[c]['title'] for c in n['children'] if c.startswith('dept-')]
                    if portfolio:description+=' The portfolios shown here are '+', '.join(portfolio)+'.'
                if re.search(r'\bfac\b|\bi/c\b|\bin.charge\b',n['title']+' '+n['sub'],re.I):limits.append('FAC / in-charge indicates an additional or temporary charge in the source listing; its current validity and written delegation must be confirmed.')
                if profile_key=='rain-shadow':limits.append('The register confirms a fiscal-year heading, not a current operational status or active programme.')
                basis='Constitutional / statutory overview' if profile_key in CORE_FAMILIES else 'Institution-specific overview' if mode=='institution' or id in BODY_IDS else 'Office-type overview'
                note='The cited constitutional or statutory framework describes the office. Current case allocation and individual delegations still apply.' if profile_key in CORE_FAMILIES else 'General explanation for the listed institution or office type. The directory confirms the listing; it does not provide a complete current duty or delegation order.'
                details={'description':description,'actions':p['actions'][:],'limits':limits,'example':p['example'],'basis':basis,'profile':profile_key,'qualified':profile_key not in CORE_FAMILIES,'sourceNote':note}
                if p['reference']:details['reference']=p['reference']
                if id=='n1061':details['reference']='https://www.hmda.gov.in/about/'
                if id=='office-human-rights-commission':details['reference']='https://www.nhrc.nic.in/assets/uploads/publication/THE%20PROTECTION%20OF%20HUMAN%20RIGHTS%20ACT-1993.pdf'
                if k=='Organization / directory heading' and profile_key=='specialist-support':unmatched_bodies.append(id)
        # Specific activity lists replace old generic filler for actual institutions and unresolved posts.
        if details['profile']=='directory':old['tasks']=['Find related published offices and institutions','Distinguish office responsibilities from navigation groupings','Open the relevant entry for role and source details']
        elif mode=='institution' or details['profile']=='specialist-support':old['tasks']=details['actions'][:]
        elif details['profile'] in {'company-secretary','government-lawyer','public-prosecution','court-registry','registrar','personal-support','board-member','chair','finance-officer','chief-executive','manager','project-officer','engineer','directorate-officer','secretariat-officer','section-officer','cmo-officer'}:
            # Prevent the old title-only classifier assigning High Court duties to a co-operative Registrar, etc.
            old['tasks']=[details['description'].split('. ')[0].rstrip('.')]+details['actions'][:2]
        if details['profile']!='directory' and (old['summary'].startswith(('Groups the offices','This post is listed','Performs the police leadership')) or mode=='institution'):
            old['summary']=PROFILES[details['profile']]['description'].split('. ')[0].rstrip('.')+'.'
        if details.get('reference'):old['source']=details['reference']
        elif details['qualified']:old['source']=n['source'] or old.get('source')
        if ctx and details['profile']!='directory':
            context_key=body_profile(ctx)
            details['contextTitle']=ctx['title']
            details['contextDescription']=(PROFILES[context_key]['description'].split('. ')[0].rstrip('.')+'.') if context_key else ctx['role']['summary']
        old.update(details)
        if details['profile']=='directory':old['summary']='Directory of related published entries; open an office or institution for its own responsibilities.'
        old['sourceNote']+= ' The example is illustrative, not a report of an action by the named incumbent.'
        counts[details['profile']]+=1
    model['roleNote']='Every entry includes a purpose, actions, authority limits and an illustrative example. Institution-specific, constitutional and general office-type overviews are labelled separately. A directory entry does not establish a person’s current appointment or exact delegated powers.'
    model['roleDetailCoverage']={'entries':len(nodes),'profiles':dict(sorted(counts.items())),'officeTypeFallbacks':fallback,'unmatchedInstitutionHeadings':unmatched_bodies,'version':1}
    return model['roleDetailCoverage']
